policy='Factual-final diagnostic: exclude independently supported ambiguous or defensible alternatives, equal correct factual finals, missing required inputs/conventions, malformed choices, or cases with actual counterexamples to both proposals. Preserve official labels on every retained pair. Format and reasoning preferences can remain defensible in the official metric; their exclusion here does not declare the official preference wrong. This is a conditional diagnostic subset, not a corrected full-benchmark accuracy. All selected questions and factual finals are reviewed after freeze without tonight\'s labels or judgement outcomes; source checks and independent computation support the listed decisions.'
excluded={x['id'] for x in exclusions};assert len(excluded)==len(exclusions)
logic={r['id'] for r in json.loads((root/'test-logic-audit.json').read_text())};puzzles={r['id'] for r in json.loads((root/'test-puzzle-audit.json').read_text())}
coverage=[{'id':x['id'],'index':i,'review':'actual proposal code executed on documented cases' if x['group']=='livecodebench' else 'exact truth-constraint proof' if x['id'] in logic else 'exhaustive position constraints' if x['id'] in puzzles else 'full question and both factual finals; arguments/source checked on ambiguity', 'decision':'exclude in factual-final diagnostic' if x['id'] in excluded else 'retain official label'} for i,x in enumerate(items)]
audit={'stamp':datetime.now(timezone.utc).isoformat(),'policy':policy,'reviewed':[x['id'] for x in items],'excluded':sorted(exclusions,key=lambda x:x['index']),'qualified_retained':qualified,'coverage':coverage,'blind_input_sha256':hashlib.sha256((root/'final-test-blind-audit.json').read_bytes()).hexdigest(),'judge_changed':False,'tonight_test_result_read_before_audit_assembly':False}
(root/'test-label-audit.json').write_text(json.dumps(audit,indent=2)+'\n')
print(json.dumps({'reviewed':len(items),'excluded':len(exclusions),'retained':len(items)-len(exclusions),'audit_sha256':hashlib.sha256((root/'test-label-audit.json').read_bytes()).hexdigest()}))
